:root{
    --ivory:#F8F5F0;
    --beige:#F0E8DA;
    --gold:#C6A16E;
    --gold-soft:#E3CFAE;
    --charcoal:#1F1F1F;
    --charcoal-soft:#8A7A66;
    --line:rgba(31,31,31,0.12);
    --ph-hero-preview:url("data:image/jpeg;base64,");
    --ph-explore-preview:url("data:image/jpeg;base64,");
    --ph-gallery-preview:url("data:image/jpeg;base64,");
    --ph-img5:url("data:image/jpeg;base64,");
    --ph-img16:url("data:image/jpeg;base64,");
    --ph-img1:url("data:image/jpeg;base64,");
    --ph-img2:url("data:image/jpeg;base64,");
    --ph-img14:url("data:image/jpeg;base64,");
    --ph-img18:url("data:image/jpeg;base64,");
    --ph-img9:url("data:image/jpeg;base64,");
    --ph-img8:url("data:image/jpeg;base64,");
    --ph-img4:url("data:image/jpeg;base64,");
    box-sizing:border-box;
    padding-top:env(safe-area-inset-top,0px);
    padding-bottom:env(safe-area-inset-bottom,0px);
  }
  *{box-sizing:inherit;margin:0;padding:0;}
  html{scroll-behavior:smooth;scroll-padding-top:env(safe-area-inset-top,0px);}
  body{
    background:var(--ivory);
    color:var(--charcoal);
    font-family:'Manrope',sans-serif;
    font-weight:400;
    line-height:1.65;
    -webkit-font-smoothing:antialiased;
    overflow-x:hidden;
  }
  h1,h2,h3,.serif{font-family:'Cormorant Garamond',serif;font-weight:600;letter-spacing:0.01em;}
  .wrap{max-width:1180px;margin:0 auto;padding:0 28px;}
  a{color:inherit;text-decoration:none;}
  img,svg{max-width:100%;display:block;}
  .container-x{width:100%;overflow-x:auto;}

  /* ---------- NAV ---------- */
  header.site{
    position:sticky;top:env(safe-area-inset-top,0px);z-index:50;
    background:rgba(251,247,241,0.92);backdrop-filter:blur(10px);
    border-bottom:1px solid var(--line);
  }
  .nav-row{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;max-width:1180px;margin:0 auto;}
  .brand{font-family:'Cormorant Garamond',serif;font-size:1.15rem;font-style:italic;letter-spacing:0.02em;}
  .brand-logo{height:34px;width:auto;}
  .footer-logo{height:40px;margin:0 auto 14px;}
  .hero-logo{height:56px;width:auto;margin-bottom:28px;animation:riseIn 1s ease-out both;}
  .wa-fab{
    position:fixed;right:20px;bottom:calc(20px + env(safe-area-inset-bottom,0px));
    width:58px;height:58px;border-radius:50%;overflow:hidden;z-index:60;
    background:var(--charcoal);box-shadow:0 10px 28px rgba(31,31,31,0.35);
    border:1px solid var(--gold);display:flex;align-items:center;justify-content:center;
    transition:transform .35s,box-shadow .35s;
  }
  .wa-fab img{width:66%;height:66%;object-fit:contain;}
  .wa-fab:hover{transform:scale(1.07);box-shadow:0 14px 34px rgba(31,31,31,0.4);}
  @media(max-width:640px){.wa-fab{width:50px;height:50px;}}
  .nav-cta{
    font-size:0.82rem;padding:10px 20px;border:1px solid var(--charcoal);
    border-radius:2px;white-space:nowrap;transition:background .3s,color .3s;
  }
  .nav-cta:hover{background:var(--charcoal);color:var(--ivory);}

  /* ---------- HERO ---------- */
  .hero{position:relative;padding:88px 0 0;overflow:hidden;}
  .hero-photo{
    width:100%;aspect-ratio:4/5;margin-top:52px;background-size:cover;background-position:center;
    position:relative;animation:riseIn 1.1s ease-out .55s both;
  }
  .hero-photo .cap{
    position:absolute;left:0;bottom:0;right:0;padding:22px 28px;
    background:linear-gradient(0deg,rgba(42,38,34,0.55),transparent);color:var(--ivory);font-size:0.82rem;letter-spacing:0.03em;
  }
  @media(min-width:860px){
    .hero .wrap{display:grid;grid-template-columns:1.05fr 0.95fr;gap:56px;align-items:center;}
    .hero-photo{margin-top:0;aspect-ratio:3/4;}
  }
  .celeb-photo{aspect-ratio:5/4;background-size:cover;background-position:center;transition:transform .6s ease;overflow:hidden;}
  .celeb-card:hover .celeb-photo{transform:scale(1.06);}
  .gplate.photo{background-size:cover;background-position:center;transition:transform .6s ease;}
  .gcard:hover .gplate.photo{transform:scale(1.07);}
  .hero-orn{
    position:absolute;right:-90px;top:-60px;width:300px;height:300px;opacity:0.5;
    animation:driftIn 1.4s ease-out both;
  }
  @keyframes driftIn{from{opacity:0;transform:translateY(-16px) scale(.94);}to{opacity:.5;transform:none;}}
  .eyebrow{
    font-size:0.78rem;color:var(--gold);letter-spacing:0.08em;
    display:inline-block;margin-bottom:22px;position:relative;padding-left:34px;
  }
  .eyebrow::before{content:"";position:absolute;left:0;top:50%;width:24px;height:1px;background:var(--gold);}
  .hero h1{
    font-size:clamp(2.5rem,7.6vw,4.2rem);line-height:1.08;max-width:11.5ch;
    animation:riseIn 1s ease-out .15s both;
  }
  @keyframes riseIn{from{opacity:0;transform:translateY(22px);}to{opacity:1;transform:none;}}
  .hero p.lede{
    margin-top:26px;max-width:44ch;color:var(--charcoal-soft);font-size:1.05rem;
    animation:riseIn 1s ease-out .3s both;
  }
  .hero-actions{display:flex;flex-wrap:wrap;gap:14px;margin-top:40px;animation:riseIn 1s ease-out .45s both;}
  .btn-primary{
    background:var(--charcoal);color:var(--ivory);padding:15px 30px;font-size:0.92rem;
    border-radius:2px;transition:background .3s;
  }
  .btn-primary:hover{background:var(--gold);}
  .btn-secondary{
    padding:15px 26px;font-size:0.92rem;border-bottom:1px solid var(--charcoal);
    transition:border-color .3s,color .3s;
  }
  .btn-secondary:hover{border-color:var(--gold);color:var(--gold);}

  /* ---------- SECTION SCAFFOLD ---------- */
  section{padding:96px 0;}
  .section-head{max-width:52ch;margin-bottom:56px;}
  .section-head .tag{font-size:0.78rem;color:var(--gold);letter-spacing:0.06em;display:block;margin-bottom:14px;}
  .section-head h2{font-size:clamp(1.9rem,4.6vw,2.6rem);line-height:1.16;}
  .section-head p{margin-top:16px;color:var(--charcoal-soft);}
  .band-beige{background:var(--beige);}

  /* ---------- CELEBRATIONS ---------- */
  .celeb-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1px;background:var(--line);border:1px solid var(--line);}
  .celeb-card{background:var(--ivory);position:relative;overflow:hidden;}
  .celeb-card .cc-body{padding:22px 22px 30px;position:relative;}
  .celeb-card .num{font-size:0.75rem;color:var(--gold);display:block;margin-bottom:16px;}
  .celeb-card h3{font-size:1.15rem;font-weight:600;}
  .celeb-card p{font-size:0.86rem;color:var(--charcoal-soft);margin-top:8px;}
  .celeb-card::after{content:"";position:absolute;left:22px;right:22px;bottom:14px;height:1px;background:var(--gold);transform:scaleX(0);transform-origin:left;transition:transform .5s ease;}
  .celeb-card:hover::after{transform:scaleX(1);}
  @media(min-width:640px){.celeb-grid{grid-template-columns:repeat(3,1fr);}}

  /* ---------- PROCESS ---------- */
  .process-list{border-top:1px solid var(--line);}
  .process-item{
    display:grid;grid-template-columns:56px 1fr;gap:22px;padding:30px 0;
    border-bottom:1px solid var(--line);
  }
  .process-item .step-num{font-family:'Cormorant Garamond',serif;font-size:1.7rem;color:var(--gold-soft);font-weight:600;}
  .process-item h3{font-size:1.2rem;margin-bottom:6px;}
  .process-item p{color:var(--charcoal-soft);max-width:56ch;}

  /* ---------- GALLERY ---------- */
  .gallery-grid{display:grid;grid-template-columns:1fr;gap:22px;}
  @media(min-width:640px){.gallery-grid{grid-template-columns:repeat(3,1fr);}}
  .gcard{border:1px solid var(--line);background:var(--ivory);overflow:hidden;}
  .gplate{
    aspect-ratio:4/5;position:relative;display:flex;align-items:center;justify-content:center;
    background:linear-gradient(155deg,var(--beige),var(--ivory) 70%);
  }
  .gplate svg{width:46%;opacity:0.9;}
  .gmeta{padding:18px 20px 22px;border-top:1px solid var(--line);}
  .gmeta .ref{font-size:0.72rem;color:var(--gold);letter-spacing:0.05em;}
  .gmeta h3{font-size:1.02rem;margin-top:6px;font-weight:450;}
  .gmeta .glinks{display:flex;gap:10px;margin-top:16px;flex-wrap:wrap;}
  .glinks a{font-size:0.76rem;padding:9px 15px;border:1px solid var(--line);border-radius:2px;letter-spacing:0.01em;transition:border-color .3s,color .3s;}
  .glinks a:hover{border-color:var(--gold);color:var(--gold);}

  /* ---------- INQUIRY ---------- */
  .inquiry-grid{display:grid;grid-template-columns:1fr;gap:48px;}
  @media(min-width:860px){.inquiry-grid{grid-template-columns:0.85fr 1.15fr;}}
  .field{margin-bottom:30px;}
  .field label{display:block;font-size:0.82rem;color:var(--charcoal-soft);margin-bottom:8px;}
  .field input,.field textarea,.field select{
    width:100%;background:transparent;border:none;border-bottom:1px solid var(--line);
    padding:11px 2px;font-family:'Manrope',sans-serif;font-size:0.98rem;color:var(--charcoal);
    transition:border-color .3s;
  }
  .field input:focus,.field textarea:focus,.field select:focus{outline:none;border-color:var(--gold);box-shadow:0 1px 0 0 var(--gold);}
  .upload-box{
    border:1px dashed var(--line);padding:26px 20px;text-align:center;font-size:0.86rem;
    color:var(--charcoal-soft);cursor:pointer;transition:border-color .3s;
  }
  .upload-box:hover{border-color:var(--gold);}
  .submit-note{font-size:0.82rem;color:var(--charcoal-soft);margin-top:16px;}
  .form-status{margin-top:18px;font-size:0.9rem;color:var(--gold);display:none;}

  /* ---------- TESTIMONIALS ---------- */
  .testi-grid{display:grid;grid-template-columns:1fr;gap:1px;background:var(--line);border:1px solid var(--line);}
  @media(min-width:760px){.testi-grid{grid-template-columns:repeat(3,1fr);}}
  .trust-badge{margin-top:22px;}
  .trust-badge .stars{color:var(--gold);letter-spacing:2px;margin-right:10px;font-size:0.95rem;}
  .trust-badge .rating{font-family:'Cormorant Garamond',serif;font-size:1.15rem;color:var(--charcoal);font-weight:600;}
  .trust-badge .verified{display:block;margin-top:6px;font-size:0.76rem;color:var(--charcoal-soft);letter-spacing:0.05em;}
  .testi-cta{text-align:center;margin-top:56px;}
  .cta-section{text-align:center;}
  .cta-section-inner{max-width:620px;margin:0 auto;}
  .cta-section-inner h2{font-size:clamp(1.9rem,4.6vw,2.5rem);line-height:1.2;}
  .cta-section-inner p{margin-top:18px;color:var(--charcoal-soft);}
  .cta-section-inner .cta-actions{display:flex;flex-wrap:wrap;justify-content:center;gap:14px;margin-top:36px;}
  .testi-cta h3{font-size:clamp(1.3rem,3.2vw,1.8rem);margin-bottom:24px;}
  .testi{
    background:var(--ivory);padding:56px 34px 40px;position:relative;overflow:hidden;
    transition:transform .45s ease,box-shadow .45s ease;
  }
  .testi::before{
    content:"";position:absolute;top:0;left:0;right:0;height:2px;background:var(--gold);
    transform:scaleX(0);transform-origin:left;transition:transform .5s ease;
  }
  .testi:hover{transform:translateY(-6px);box-shadow:0 20px 44px rgba(31,31,31,0.10);z-index:2;}
  .testi:hover::before{transform:scaleX(1);}
  .testi .stars-row{color:var(--gold);font-size:0.72rem;letter-spacing:4px;opacity:0.9;margin-bottom:18px;}
  .testi .qmark{
    position:absolute;top:2px;left:28px;font-family:'Cormorant Garamond',serif;font-size:4.6rem;
    color:var(--gold-soft);opacity:0.55;line-height:1;pointer-events:none;
  }
  .testi q{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:1.3rem;line-height:1.55;display:block;quotes:none;position:relative;z-index:1;}
  .testi .who{margin-top:26px;font-size:0.95rem;color:var(--charcoal);font-weight:600;display:flex;flex-direction:column;gap:6px;}
  .testi .who span{color:var(--gold);font-size:0.72rem;letter-spacing:0.08em;font-weight:500;}

  /* ---------- RESERVE ---------- */
  .reserve{background:var(--charcoal);color:var(--ivory);text-align:center;}
  .reserve h2{color:var(--ivory);font-size:clamp(1.8rem,5vw,2.5rem);max-width:20ch;margin:0 auto;}
  .reserve p{color:#C9C2B6;max-width:48ch;margin:18px auto 0;}
  .reserve .btn-primary{background:var(--gold);color:var(--charcoal);margin-top:34px;display:inline-block;}
  .reserve .btn-primary:hover{background:var(--ivory);}

  /* ---------- CONTACT ---------- */
  .contact-grid{display:grid;grid-template-columns:1fr;gap:1px;background:var(--line);border:1px solid var(--line);}
  @media(min-width:720px){.contact-grid{grid-template-columns:repeat(3,1fr);}}
  .ccard{background:var(--ivory);padding:32px 26px;transition:background .3s;}
  .ccard:hover{background:var(--beige);}
  .ccard .tag{font-size:0.75rem;color:var(--gold);display:block;margin-bottom:10px;}
  .ccard h3{font-size:1.08rem;font-weight:450;margin-bottom:6px;}
  .ccard p{font-size:0.86rem;color:var(--charcoal-soft);}

  footer{padding:44px 0;text-align:center;font-size:0.8rem;color:var(--charcoal-soft);border-top:1px solid var(--line);}
  footer .brand-logo{display:block;margin-left:auto;margin-right:auto;}


  /* ---------- STATS ---------- */
  .stats-strip{padding:48px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);}
  .trust-statement{max-width:640px;margin:0 auto;text-align:center;padding:20px 0;}
  .trust-statement h3{font-size:clamp(1.4rem,3.2vw,1.9rem);line-height:1.35;font-weight:600;}
  .trust-statement p{margin-top:18px;color:var(--charcoal-soft);font-size:0.98rem;line-height:1.7;}

  /* ---------- INSTAGRAM ---------- */
  .insta-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:2px;}
  @media(min-width:640px){.insta-grid{grid-template-columns:repeat(4,1fr);}}
  .insta-item{aspect-ratio:1/1;background-size:cover;background-position:center;display:block;position:relative;overflow:hidden;}
  .insta-item::after{content:"";position:absolute;inset:0;background:rgba(31,31,31,0);transition:background .35s;}
  .insta-item:hover::after{background:rgba(31,31,31,0.15);}

  /* ---------- FOOTER LINKS ---------- */
  .footer-links{display:flex;flex-wrap:wrap;justify-content:center;gap:18px;margin:14px 0;font-size:0.82rem;}
  .footer-links a{transition:color .3s;}
  .footer-links a:hover{color:var(--gold);}
  .footer-copy{margin-top:14px;font-size:0.75rem;color:var(--charcoal-soft);}

  .trust-strip{padding:40px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);}
  .trust-strip-inner{display:flex;flex-direction:column;align-items:center;gap:20px;text-align:center;}
  @media(min-width:760px){.trust-strip-inner{flex-direction:row;justify-content:space-between;text-align:left;}}
  .trust-rating{white-space:nowrap;}
  .trust-rating .stars{color:var(--gold);letter-spacing:3px;margin-right:10px;font-size:0.95rem;}
  .trust-rating .rating{font-family:'Cormorant Garamond',serif;font-size:1.15rem;color:var(--charcoal);font-weight:600;}
  .trust-items{display:flex;flex-wrap:wrap;justify-content:center;gap:12px 28px;}
  .trust-items span{position:relative;font-size:0.8rem;color:var(--charcoal-soft);letter-spacing:0.03em;padding-right:28px;}
  .trust-items span::after{content:"";position:absolute;right:0;top:50%;width:4px;height:4px;border-radius:50%;background:var(--gold);transform:translateY(-50%);}
  .trust-items span:last-child{padding-right:0;}
  .trust-items span:last-child::after{display:none;}
  @media(max-width:759px){.trust-items{flex-direction:column;gap:10px;}.trust-items span{padding-right:0;}.trust-items span::after{display:none;}}


  /* ---------- SCROLL REVEAL ---------- */
  .reveal{opacity:0;transform:translateY(18px);transition:opacity .7s ease,transform .7s ease;}
  .reveal.in-view{opacity:1;transform:none;}

  @media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;}}
